#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;

static vector<P> pts, tmp;
static const ll INF = LLONG_MAX;

static ll sq(ll v) { return v * v; }

// Returns the closest squared distance in pts[lo,hi) and leaves that range sorted by y.
static ll visit(int lo, int hi) {
    if (hi - lo <= 3) {
        ll best = INF;
        for (int i = lo; i < hi; i++)
            for (int j = lo; j < i; j++)
                best = min(best, sq(pts[i].first - pts[j].first) + sq(pts[i].second - pts[j].second));
        sort(pts.begin() + lo, pts.begin() + hi, [](const P &a, const P &b) { return a.second < b.second; });
        return best;
    }
    int mid = (lo + hi) / 2;
    ll cut = pts[mid].first;
    ll best = min(visit(lo, mid), visit(mid, hi));
    merge(pts.begin() + lo, pts.begin() + mid, pts.begin() + mid, pts.begin() + hi, tmp.begin() + lo,
          [](const P &a, const P &b) { return a.second < b.second; });
    copy(tmp.begin() + lo, tmp.begin() + hi, pts.begin() + lo);
    // Strip: points whose squared distance to the dividing line is below best.
    vector<P> strip;
    for (int i = lo; i < hi; i++)
        if (sq(pts[i].first - cut) < best) strip.push_back(pts[i]);
    for (size_t i = 0; i < strip.size(); i++)
        for (size_t j = i + 1; j < strip.size() && sq(strip[j].second - strip[i].second) < best; j++)
            best = min(best, sq(strip[i].first - strip[j].first) + sq(strip[i].second - strip[j].second));
    return best;
}

int main() {
    int n;
    scanf("%d", &n);
    pts.resize(n);
    tmp.resize(n);
    for (auto &p : pts) scanf("%lld %lld", &p.first, &p.second);
    sort(pts.begin(), pts.end());
    for (int i = 1; i < n; i++)
        if (pts[i] == pts[i - 1]) {
            puts("0");
            return 0;
        }
    printf("%lld\n", visit(0, n));
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static long[] xs, ys, tx, ty, sx, sy;
    static final long INF = Long.MAX_VALUE;

    // Returns the closest squared distance in [lo,hi) and leaves that range sorted by y.
    static long visit(int lo, int hi) {
        if (hi - lo <= 3) {
            long best = INF;
            for (int i = lo; i < hi; i++)
                for (int j = lo; j < i; j++) {
                    long dx = xs[i] - xs[j], dy = ys[i] - ys[j];
                    best = Math.min(best, dx * dx + dy * dy);
                }
            for (int i = lo + 1; i < hi; i++) // insertion sort by y
                for (int j = i; j > lo && ys[j] < ys[j - 1]; j--) {
                    long t = xs[j]; xs[j] = xs[j - 1]; xs[j - 1] = t;
                    t = ys[j]; ys[j] = ys[j - 1]; ys[j - 1] = t;
                }
            return best;
        }
        int mid = (lo + hi) >>> 1;
        long cut = xs[mid];
        long best = Math.min(visit(lo, mid), visit(mid, hi));
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi) {
            if (ys[i] <= ys[j]) { tx[k] = xs[i]; ty[k++] = ys[i++]; }
            else { tx[k] = xs[j]; ty[k++] = ys[j++]; }
        }
        while (i < mid) { tx[k] = xs[i]; ty[k++] = ys[i++]; }
        while (j < hi) { tx[k] = xs[j]; ty[k++] = ys[j++]; }
        System.arraycopy(tx, lo, xs, lo, hi - lo);
        System.arraycopy(ty, lo, ys, lo, hi - lo);
        // Strip: points whose squared distance to the dividing line is below best.
        int m = 0;
        for (int p = lo; p < hi; p++) {
            long d = xs[p] - cut;
            if (d * d < best) { sx[lo + m] = xs[p]; sy[lo + m] = ys[p]; m++; }
        }
        for (int a = lo; a < lo + m; a++)
            for (int b = a + 1; b < lo + m; b++) {
                long dy = sy[b] - sy[a];
                if (dy * dy >= best) break;
                long dx = sx[b] - sx[a];
                best = Math.min(best, dx * dx + dy * dy);
            }
        return best;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] key = new long[n];
        xs = new long[n]; ys = new long[n]; tx = new long[n]; ty = new long[n]; sx = new long[n]; sy = new long[n];
        // Coordinates < 2^30: pack (x, y) into one long to sort by x then y.
        for (int i = 0; i < n; i++) key[i] = nextLong() << 30 | nextLong();
        Arrays.sort(key);
        for (int i = 0; i < n; i++) {
            if (i > 0 && key[i] == key[i - 1]) {
                System.out.println(0);
                return;
            }
            xs[i] = key[i] >>> 30;
            ys[i] = key[i] & ((1L << 30) - 1);
        }
        System.out.println(visit(0, n));
    }
}

package main

import (
	"fmt"
	"io"
	"math"
	"os"
	"slices"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

type pt struct{ x, y int64 }

var pts, tmp, strip []pt

func sq(v int64) int64 { return v * v }

// visit returns the closest squared distance in pts[lo:hi] and leaves that range sorted by y.
func visit(lo, hi int) int64 {
	if hi-lo <= 3 {
		best := int64(math.MaxInt64)
		for i := lo; i < hi; i++ {
			for j := lo; j < i; j++ {
				best = min(best, sq(pts[i].x-pts[j].x)+sq(pts[i].y-pts[j].y))
			}
		}
		slices.SortFunc(pts[lo:hi], func(a, b pt) int {
			if a.y < b.y {
				return -1
			}
			if a.y > b.y {
				return 1
			}
			return 0
		})
		return best
	}
	mid := (lo + hi) / 2
	cut := pts[mid].x
	best := min(visit(lo, mid), visit(mid, hi))
	i, j, k := lo, mid, lo
	for i < mid && j < hi {
		if pts[i].y <= pts[j].y {
			tmp[k] = pts[i]
			i++
		} else {
			tmp[k] = pts[j]
			j++
		}
		k++
	}
	k += copy(tmp[k:], pts[i:mid])
	copy(tmp[k:], pts[j:hi])
	copy(pts[lo:hi], tmp[lo:hi])
	// Strip: points whose squared distance to the dividing line is below best.
	s := strip[lo:lo]
	for p := lo; p < hi; p++ {
		if sq(pts[p].x-cut) < best {
			s = append(s, pts[p])
		}
	}
	for a := 0; a < len(s); a++ {
		for b := a + 1; b < len(s) && sq(s[b].y-s[a].y) < best; b++ {
			best = min(best, sq(s[a].x-s[b].x)+sq(s[a].y-s[b].y))
		}
	}
	return best
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	pts = make([]pt, n)
	tmp = make([]pt, n)
	strip = make([]pt, n)
	for i := range pts {
		pts[i] = pt{nextInt(), nextInt()}
	}
	slices.SortFunc(pts, func(a, b pt) int {
		if a.x != b.x {
			if a.x < b.x {
				return -1
			}
			return 1
		}
		if a.y < b.y {
			return -1
		}
		if a.y > b.y {
			return 1
		}
		return 0
	})
	for i := 1; i < n; i++ {
		if pts[i] == pts[i-1] {
			fmt.Println(0)
			return
		}
	}
	fmt.Println(visit(0, n))
}
